#!/usr/bin/env bash
# PreToolUse hook for Bash: blocks recursive forced deletes (rm -rf and equivalents).
# Reads the hook event JSON on stdin. Exit 2 blocks the call and sends stderr to Claude.
# Any failure to run this script is treated as a block (see onFailure in hooks/hooks.json).

exec python3 -I -c '
import json, os, shlex, sys

OPERATORS = {";", ";;", "&", "&&", "|", "|&", "||", "(", ")", "{", "}", "\n"}

def rm_rf_args(args):
    recursive = force = False
    for arg in args:
        if arg == "--":
            break
        if arg.startswith("--"):
            recursive |= arg == "--recursive"
            force |= arg == "--force"
        elif arg.startswith("-") and len(arg) > 1:
            recursive |= "r" in arg or "R" in arg
            force |= "f" in arg
    return recursive and force

def is_blocked(command):
    # Newlines separate commands in bash, so treat them as operators.
    lexer = shlex.shlex(command.replace("\n", " ; "), posix=True, punctuation_chars=True)
    lexer.whitespace_split = True
    try:
        tokens = list(lexer)
    except ValueError:
        # Unbalanced quotes: fall back to a plain split so the check still runs.
        tokens = command.split()
    for i, token in enumerate(tokens):
        if token not in OPERATORS and os.path.basename(token) == "rm":
            args = []
            for following in tokens[i + 1:]:
                if following in OPERATORS:
                    break
                args.append(following)
            if rm_rf_args(args):
                return True
        # Catch rm hidden inside a string, e.g. bash -c "rm -rf x" or eval.
        elif token not in OPERATORS and "rm" in token and is_blocked(token):
            return True
    return False

event = json.load(sys.stdin)
if event.get("tool_name") != "Bash":
    sys.exit(0)
command = event.get("tool_input", {}).get("command", "")
if is_blocked(command):
    sys.stderr.write(
        "Blocked: rm -rf (recursive + forced delete) is not allowed in this project. "
        "Remove specific files by name, or ask the user to run the command themselves.\n"
    )
    sys.exit(2)
sys.exit(0)
' "$@"
