#!/usr/bin/env bash
# PreToolUse hook: block any Bash command that runs `rm` with both recursive and
# force flags (rm -rf, -fr, -Rf, -r -f, --recursive --force, ...), including when
# it is wrapped in sudo/xargs/find -exec or passed to sh -c / eval.
# Reads the event JSON on stdin. Exit 2 blocks the call; stderr is shown to Claude.

payload=$(cat)

printf '%s' "$payload" | python3 -I -c '
import json, re, shlex, sys

SHELLS = {"sh", "bash", "zsh", "dash", "eval"}

def rm_rf_args(args):
    rec = force = False
    for a in args:
        if a == "--":
            break
        if a.startswith("--") and len(a) > 2:
            rec = rec or "--recursive".startswith(a)
            force = force or "--force".startswith(a)
        elif a.startswith("-") and len(a) > 1:
            rec = rec or "r" in a or "R" in a
            force = force or "f" in a
    return rec and force

def blocked(text, depth=0):
    if depth > 5:
        return False
    for seg in re.split(r"[;&|\n()`]", text):
        try:
            toks = shlex.split(seg)
        except ValueError:
            toks = seg.split()
        for i, t in enumerate(toks):
            head = t.rsplit("/", 1)[-1].lstrip("\\")
            if head == "rm" and rm_rf_args(toks[i + 1:]):
                return True
            if head in SHELLS:
                if any(blocked(a, depth + 1) for a in toks[i + 1:]):
                    return True
    return False

try:
    event = json.load(sys.stdin)
except ValueError:
    sys.exit(0)
if event.get("tool_name") != "Bash":
    sys.exit(0)
command = (event.get("tool_input") or {}).get("command", "")
if blocked(command):
    sys.stderr.write(
        "Blocked: rm -rf is not allowed in this project. Remove the specific files "
        "by name (or use git rm), and ask the user before any recursive delete.\n"
    )
    sys.exit(2)
'

